import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { randomBytes } from 'node:crypto';
import path from 'node:path';

// Books live in memory and every change is written back to a JSON file.
// Writes go to a temp file first and are renamed into place, so a crash
// mid-write can't leave a half-written books.json behind.
export async function openStore(file) {
  let books = [];
  try {
    books = JSON.parse(await readFile(file, 'utf8'));
  } catch (err) {
    // A missing file just means no books yet. Anything else (e.g. a corrupt
    // file) should stop the app rather than silently start from empty and
    // overwrite the user's data on the next save.
    if (err.code !== 'ENOENT') throw err;
  }

  let pending = Promise.resolve();
  function save() {
    const json = JSON.stringify(books, null, 2) + '\n';
    pending = pending
      .catch(() => {})
      .then(async () => {
        await mkdir(path.dirname(file), { recursive: true });
        const tmp = `${file}.tmp`;
        await writeFile(tmp, json);
        await rename(tmp, file);
      });
    return pending;
  }

  function newId() {
    let id;
    do id = randomBytes(6).toString('base64url');
    while (books.some((b) => b.id === id));
    return id;
  }

  return {
    reading() {
      return books
        .filter((b) => !b.finishedAt)
        .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
    },

    finished() {
      return books
        .filter((b) => b.finishedAt)
        .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
    },

    get(id) {
      return books.find((b) => b.id === id);
    },

    async add({ title, author = '', notes = '' }) {
      const book = {
        id: newId(),
        title,
        author,
        notes,
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },

    async finish(id) {
      const book = this.get(id);
      if (!book) return undefined;
      if (!book.finishedAt) {
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

