const escapeMap = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escape(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => escapeMap[c]);
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #1a5fb4; }
  h1 a { color: inherit; text-decoration: none; }
  ul { list-style: none; padding: 0; }
  li { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #666; }
  .empty { color: #888; font-style: italic; }
  form.add { display: grid; gap: .5rem; padding: 1rem; background: #f6f6f6; border-radius: 6px; }
  input, textarea, button { font: inherit; }
  input, textarea { padding: .4rem; border: 1px solid #ccc; border-radius: 4px; }
  button { padding: .3rem .8rem; cursor: pointer; }
  .notes { white-space: pre-wrap; background: #f6f6f6; padding: 1rem; border-radius: 6px; }
  .error { color: #b00020; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function finishButton(book, from) {
  return `<form method="post" action="/books/${escape(book.id)}/finish">
  <input type="hidden" name="from" value="${from}">
  <button type="submit">Mark finished</button>
</form>`;
}

function bookLink(book) {
  const by = book.author ? ` <span class="muted">by ${escape(book.author)}</span>` : '';
  return `<span><a href="/books/${escape(book.id)}">${escape(book.title)}</a>${by}</span>`;
}

export function homePage({ reading, finished, error, values = {} }) {
  const readingList = reading.length
    ? `<ul>${reading.map((b) => `<li>${bookLink(b)}${finishButton(b, 'home')}</li>`).join('')}</ul>`
    : '<p class="empty">Nothing on the go right now.</p>';

  const finishedList = finished.length
    ? `<ul>${finished
        .map((b) => `<li>${bookLink(b)}<span class="muted">${formatDate(b.finishedAt)}</span></li>`)
        .join('')}</ul>`
    : '<p class="empty">No finished books yet.</p>';

  return layout(
    'My books',
    `<h2>Currently reading</h2>
${readingList}
<h2>Finished</h2>
${finishedList}
<h2>Add a book</h2>
<form class="add" method="post" action="/books">
  ${error ? `<p class="error">${escape(error)}</p>` : ''}
  <label>Title <input name="title" required maxlength="300" value="${escape(values.title)}"></label>
  <label>Author <input name="author" maxlength="300" value="${escape(values.author)}"></label>
  <label>Notes <textarea name="notes" rows="4" maxlength="20000">${escape(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book) {
  const status = book.finishedAt
    ? `<p class="muted">Finished ${formatDate(book.finishedAt)}</p>`
    : `<p class="muted">Currently reading (added ${formatDate(book.addedAt)})</p>${finishButton(book, 'book')}`;

  return layout(
    book.title,
    `<h2>${escape(book.title)}</h2>
<p>${book.author ? `by ${escape(book.author)}` : '<span class="empty">Unknown author</span>'}</p>
${status}
<h3>Notes</h3>
${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : '<p class="empty">No notes.</p>'}
<p><a href="/">&larr; All books</a></p>`,
  );
}

export function notFoundPage() {
  return layout('Not found', `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`);
}

