import http from 'node:http';
import { bookPage, homePage, notFoundPage } from './views.js';

const MAX_BODY_BYTES = 100_000;

function send(res, status, html) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

async function readForm(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > MAX_BODY_BYTES) throw Object.assign(new Error('Body too large'), { status: 413 });
  }
  return new URLSearchParams(body);
}

export function createApp(store) {
  async function handle(req, res) {
    const { pathname } = new URL(req.url, 'http://localhost');
    const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
    const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);

    if (req.method === 'GET' && pathname === '/') {
      return send(res, 200, homePage({ reading: store.reading(), finished: store.finished() }));
    }

    if (req.method === 'POST' && pathname === '/books') {
      const form = await readForm(req);
      const values = {
        title: (form.get('title') ?? '').trim(),
        author: (form.get('author') ?? '').trim(),
        notes: (form.get('notes') ?? '').trim(),
      };
      if (!values.title) {
        const page = homePage({ reading: store.reading(), finished: store.finished(), error: 'Please give the book a title.', values });
        return send(res, 400, page);
      }
      await store.add(values);
      return redirect(res, '/');
    }

    if (req.method === 'GET' && bookMatch) {
      const book = store.get(bookMatch[1]);
      return book ? send(res, 200, bookPage(book)) : send(res, 404, notFoundPage());
    }

    if (req.method === 'POST' && finishMatch) {
      const form = await readForm(req);
      const book = await store.finish(finishMatch[1]);
      if (!book) return send(res, 404, notFoundPage());
      return redirect(res, form.get('from') === 'book' ? `/books/${book.id}` : '/');
    }

    send(res, 404, notFoundPage());
  }

  return http.createServer((req, res) => {
    handle(req, res).catch((err) => {
      if (!err.status) console.error(err);
      if (!res.headersSent) send(res, err.status ?? 500, 'Something went wrong.');
    });
  });
}

