import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { openStore } from '../src/store.js';

let dir, dataFile, server, base;

async function start() {
  const store = await openStore(dataFile);
  server = createApp(store);
  await new Promise((resolve) => server.listen(0, resolve));
  base = `http://localhost:${server.address().port}`;
}

async function stop() {
  await new Promise((resolve) => server.close(resolve));
}

function post(pathname, fields) {
  return fetch(base + pathname, { method: 'POST', body: new URLSearchParams(fields), redirect: 'manual' });
}

async function addBook(fields) {
  await post('/books', fields);
  const saved = JSON.parse(await readFile(dataFile, 'utf8'));
  return saved.find((b) => b.title === fields.title);
}

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), 'books-'));
  dataFile = path.join(dir, 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('books app', () => {
  it('shows empty lists when there are no books', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
  });

  it('adds a book from the form and lists it as currently reading', async () => {
    const res = await post('/books', { title: 'Middlemarch', author: 'George Eliot', notes: 'Slow start' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const html = await (await fetch(base + '/')).text();
    const reading = html.split('<h2>Finished</h2>')[0];
    expect(reading).toContain('Middlemarch');
    expect(reading).toContain('George Eliot');
  });

  it('rejects a book without a title and keeps what was typed', async () => {
    const res = await post('/books', { title: '  ', author: 'Someone' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please give the book a title.');
    expect(html).toContain('value="Someone"');
  });

  it('shows a book page with title, author and notes at a shareable URL', async () => {
    const book = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Line one\nLine two' });
    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Dune');
    expect(html).toContain('by Frank Herbert');
    expect(html).toContain('Line one\nLine two');
  });

  it('marks a book as finished', async () => {
    const book = await addBook({ title: 'Emma' });
    const res = await post(`/books/${book.id}/finish`, { from: 'book' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);

    const html = await (await fetch(base + '/')).text();
    const [reading, finished] = html.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Emma');
    expect(finished).toContain('Emma');
  });

  it('returns 404 for unknown books', async () => {
    expect((await fetch(`${base}/books/nope`)).status).toBe(404);
    expect((await post('/books/nope/finish', {})).status).toBe(404);
  });

  it('escapes HTML in user input', async () => {
    const book = await addBook({ title: '<script>alert(1)</script>', notes: '<b>hi</b>' });
    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;');
    expect(html).not.toContain('<b>hi</b>');
  });

  it('keeps books after a restart', async () => {
    const book = await addBook({ title: 'Persuasion', author: 'Jane Austen' });
    await post(`/books/${book.id}/finish`, {});
    await stop();
    await start();

    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).toContain('Persuasion');
    expect(html).toContain('Finished');
  });

  it('refuses to start over a corrupt data file instead of wiping it', async () => {
    await writeFile(dataFile, '{not json');
    await expect(openStore(dataFile)).rejects.toThrow();
    expect(await readFile(dataFile, 'utf8')).toBe('{not json');
  });
});

